  "implementation": "import math

def solve(case):
    matrix = case['payload']['matrix']
    if not matrix or not matrix[0]:
        raise ValueError('Empty matrix')
    n_rows = len(matrix)
    n_cols = len(matrix[0])
    for row in matrix:
        if len(row) != n_cols:
            raise ValueError('Inconsistent row lengths')
    # document frequency per column
    df = [0] * n_cols
    for row in matrix:
        for j, val in enumerate(row):
            if val != 0:
                df[j] += 1
    # compute IDF
    idf = [0.0] * n_cols
    for j in range(n_cols):
        idf[j] = math.log(1 + n_rows / (1 + df[j]))
    # build weighted matrix and degrees
    weighted_matrix = []
    degrees = []
    for i in range(n_rows):
        new_row = []
        row_sum = 0.0
        for j in range(n_cols):
            val = matrix[i][j]
            if val != 0:
                w = val * idf[j]
                # self-similarity removal: if i == j and matrix is square? not applicable
            else:
                w = 0.0
            new_row.append(round(w, 4))
            row_sum += w
        weighted_matrix.append(new_row)
        degrees.append(round(row_sum, 4))
    # round idf values
    idf_rounded = [round(v, 4) for v in idf]
    return {
        'idf': idf_rounded,
        'weighted_matrix': weighted_matrix,
        'degrees': degrees
    }"
}
